/**
 * Closed lifecycle states for a `EvidenceBundle`'s verification status.
 *
 * `PENDING` is the initial state when a bundle is first written. `VERIFIED`
 * means all `VerificationCheck` items passed. `INCOMPLETE` means reachability
 * or digest checks found missing records but the operator accepted the partial
 * bundle. `FAILED` means at least one blocking integrity check failed.
 */
export type BundleVerificationState =
  "pending" | "verified" | "incomplete" | "failed";

/**
 * One referenced record entry inside an `EvidenceBundle` manifest.
 *
 * `object_type` names the `BucketEventObjectType` of the record; `object_id`
 * is its stable store key; `content_sha256` is the canonical `ContentDigest`
 * of the record's raw payload bytes, so a non-hex digest is refused on
 * construction rather than at the later verification pass that recomputes it;
 * `payload_size_bytes` is the byte count used for completeness-ratio
 * calculation.
 */
export type EvidenceRecordRef = {
  object_type: BucketEventObjectType;
  object_id: string;
  content_sha256: ContentDigest;
  payload_size_bytes: number;
};

